function(args) {
  try {
    var m = document.cookie.match(/(?:^|;\s*)locale=([^;]+)/);
    var locale = m ? decodeURIComponent(m[1]).trim().toLowerCase() : null;
    if (!locale) {
      var lang = (document.documentElement.getAttribute('lang') || '').trim().toLowerCase();
      locale = lang || 'en';
    }
    return locale === 'en' || locale.indexOf('en_') === 0 || locale.indexOf('en-') === 0;
  } catch (e) {
    return false;
  }
}

