function(args) {
  var metricName = 'Sign - Homepage Hero – Free Trial CTA Click';
  var SELECTOR = '.section_n-hero a[data-trackingid="homepage_bottom_plank_trial_cta"]';

  console.warn('[CFQ Metric] js_binder loaded — "' + metricName + '" — watching ' + SELECTOR);

  document.addEventListener('mousedown', function(e) {
    if (!e.target || !e.target.closest) return;

    var hit = e.target.closest(SELECTOR);
    if (!hit) return;

    console.warn('[CFQ Metric] SUCCESS: homepage hero free-trial CTA clicked — firing conversion for metricId: ' + args.metricId);

    window.CFQ = window.CFQ || [];
    window.CFQ.push({
      emit: 'conversion',
      payload: {
        metricId: args.metricId,
        metricName: metricName
      }
    });
  }, true);
}

/**
 * Dropbox Sign - Homepage – Get a Demo CTA Click
 *
 * Fires on clicks of the "Get a demo" CTAs in the redesigned homepage (#home-new).
 *
 * Selector rationale:
 *   - Anchored to href*="_tk=cf_DBXS-001_v3" — the attribution param carried by
 *     both demo links. Unique to them.
 *   - Class .button-link_n-icon was REJECTED as an anchor: it is shared with
 *     three unrelated resource links and would over-count.
 *   - Previous hooks (#cf-get-demo-btn, .cf-demo-btn) are dead — they were
 *     injected by the DBXS-001 Coframe variant and are absent now that the
 *     redesign ships the CTAs natively.
 *
 * Arm behaviour:
 *   - #home-new (variant): 2 matching links -> can fire
 *   - #home-old (control): 0 matching links -> structurally zero
 *   Do NOT read this as a between-arm comparison.
 *
 * Method: delegated mousedown listener, capture phase, fire-once per page load.
 */

function (args) {
  var metricName = 'Sign - Homepage – Get a Demo CTA Click';
  var SELECTOR = 'a[href*="_tk=cf_DBXS-001_v3"]';
  var fired = false;

  console.warn('[Coframe][' + metricName + '] binder attached; watching ' + SELECTOR);

  document.addEventListener(
    'mousedown',
    function (e) {
      if (fired) return;
      if (!e.target || !e.target.closest) return;

      var hit = e.target.closest(SELECTOR);
      if (!hit) return;

      fired = true;
      console.warn('[Coframe][' + metricName + '] demo CTA click matched:', hit.textContent.trim());

      window.CFQ = window.CFQ || [];
      window.CFQ.push({
        emit: 'conversion',
        payload: {
          metricId: args.metricId,
          metricName: metricName
        }
      });
    },
    true
  );
}

/**
 * Dropbox Sign - Contact Sales Form – Submit
 *
 * Tracks successful submissions of the Contact Us form on
 * https://sign.dropbox.com/form/contact-us-general
 *
 * Two success signals, either counts once (deduped via shared `submitted` flag):
 *
 *   A) GTM auto-event listener (original):
 *      { event: "gtm.formSubmit", "gtm.elementUrl": "https://sign.dropbox.com/form/contact-us-general?..." }
 *      Matched on event + gtm.elementUrl path-prefix (query string varies per session).
 *
 *   B) App-level completion event (new):
 *      { event: "track_event", eventAction: "/form/contact-us-general",
 *        eventCategory: "contactus-form-complete", eventLabel: "/thankyou" }
 *
 * Pattern (per canonical dataLayer metric rules):
 *  1. Scan existing window.dataLayer entries on init (catch events that fired
 *     before our wrapper installed).
 *  2. Wrap dataLayer.push for future events, guarded so we never double-wrap.
 *  3. Per-page dedupe guard (submitted flag) — count once per successful submit.
 */
function(args) {
    const metricName = 'Sign - Contact Sales Form – Submit'

    // Signal A: GTM auto-event form submit
    const FORM_SUBMIT_EVENT = 'gtm.formSubmit'
    const URL_PREFIX = 'https://sign.dropbox.com/form/contact-us-general'

    // Signal B: app-level completion track_event
    const TRACK_EVENT = 'track_event'
    const TRACK_ACTION = '/form/contact-us-general'
    const TRACK_CATEGORY = 'contactus-form-complete'
    const TRACK_LABEL = '/thankyou'

    let submitted = false

    const reportConversion = (sourcePath) => {
        if (submitted) return
        submitted = true
        console.log('[Coframe] ' + metricName + ' detected via ' + sourcePath + ' — metric sent')
        window.CFQ = window.CFQ || []
        window.CFQ.push({
            emit: 'conversion',
            payload: {
                metricId: args.metricId
            },
        })
    }

    // Signal A matcher (unchanged)
    const isFormSubmitMatch = (entry) => {
        try {
            if (!entry || typeof entry !== 'object') return false
            if (entry.event !== FORM_SUBMIT_EVENT) return false
            const url = entry['gtm.elementUrl']
            return typeof url === 'string' && url.indexOf(URL_PREFIX) === 0
        } catch (e) {
            return false
        }
    }

    // Signal B matcher (new)
    const isTrackEventMatch = (entry) => {
        try {
            if (!entry || typeof entry !== 'object') return false
            return entry.event === TRACK_EVENT &&
                   entry.eventAction === TRACK_ACTION &&
                   entry.eventCategory === TRACK_CATEGORY &&
                   entry.eventLabel === TRACK_LABEL
        } catch (e) {
            return false
        }
    }

    const checkEntry = (entry) => {
        if (isFormSubmitMatch(entry)) {
            reportConversion('dataLayer (gtm.formSubmit)')
            return true
        }
        if (isTrackEventMatch(entry)) {
            reportConversion('dataLayer (track_event / contactus-form-complete)')
            return true
        }
        return false
    }

    const start = () => {
        console.log('[Coframe] watcher loaded for: ' + metricName)
        window.dataLayer = window.dataLayer || []

        // 1. Scan entries that already fired before we installed our wrapper.
        try {
            for (let i = 0; i < window.dataLayer.length; i++) {
                if (checkEntry(window.dataLayer[i])) break
            }
        } catch (e) {
            console.warn('[Coframe] ' + metricName + ' dataLayer scan error', e)
        }

        // 2. Wrap push for future events, guarded so we never double-wrap.
        if (!window.dataLayer.__cfContactSubmitWrapped) {
            const origPush = window.dataLayer.push
            window.dataLayer.push = function() {
                try {
                    for (let i = 0; i < arguments.length; i++) {
                        checkEntry(arguments[i])
                    }
                } catch (e) {
                    console.warn('[Coframe] ' + metricName + ' push handler error', e)
                }
                return origPush.apply(this, arguments)
            }
            window.dataLayer.__cfContactSubmitWrapped = true
        }
    }

    if (document.body) start()
    else document.addEventListener('DOMContentLoaded', start)
}

/**
 * Core - DocSend Hero – Primary CTA Click
 *
 * Tracks clicks on the primary CTA in the /docsend hero.
 * Stable across control ("Try DocSend") and DBX-039 Problem→Solution variant
 * ("Get actionable insights") because the selector targets the
 * [data-trackingid='docsend_dwg_hero_l3_plank-fb1fcd2a48_cta_primary_button--1']
 * attribute, which is preserved in the variant build (copy-only change).
 *
 * Tracking method:
 * - Delegated mousedown listener on document (capture phase). mousedown fires
 *   before navigation to https://docsend.com/signup, so the conversion is sent
 *   reliably even though the click navigates away.
 *
 * Dedupe:
 * - None. Every click is counted (per canonical metric guide §1, matches GA4).
 */
function(args) {
    const metricName = 'Core - DocSend Hero – Primary CTA Click'

    const startObserver = () => {
        console.log(`[Coframe] watcher loaded for: ${metricName}`)

        const ctaSelector = `a[data-trackingid='docsend_dwg_hero_l3_plank-fb1fcd2a48_cta_primary_button--1']`

        const reportConversion = () => {
            console.log(`[Coframe] ${metricName} detected and metric sent`)

            window.CFQ = window.CFQ || []
            window.CFQ.push({
                emit: 'conversion',
                payload: {
                    metricId: args.metricId
                },
            })
        }

        document.addEventListener('mousedown', function(e) {
            var match = e.target.closest(ctaSelector)
            if (match) {
                reportConversion()
            }
        }, true)
    }

    if (document.body) startObserver()
    else document.addEventListener('DOMContentLoaded', startObserver)
}

/**
 * Core - /Plans – Plan CTA Click (Primary metric for DBX-043 Annual Value Badge)
 *
 * Tracks clicks on the primary conversion CTAs in the plan cards on /plans:
 *   - "Buy now"        (direct purchase)
 *   - "Try for free"   (trial start)
 *   - "or buy now"     (direct purchase secondary link)
 *
 * These CTAs are dwg-button2 <button> elements with NO href/data-trackingid,
 * so the binder matches on normalized visible button text.
 *
 * EXCLUDED by design:
 *   - "View all features" (anchor jump, not a plan selection)
 *   - "Get Basic" (/register free tier, not a paid plan selection)
 *   - "Contact us" / "Contact sales" (enterprise routing, not self-serve)
 *
 * Stable across control + both badge variants because the badge change does not
 * alter the plan-card CTA buttons themselves.
 *
 * Tracking method:
 * - Delegated mousedown listener on document (capture phase). mousedown fires
 *   before navigation so the conversion is sent reliably even when the click
 *   navigates away. Survives SPA re-renders because it is delegated on document.
 *
 * Dedupe:
 * - None. Every qualifying click is counted (per canonical metric guide §1).
 */
function(args) {
    const metricName = 'Core - /Plans – Plan CTA Click'

    const startObserver = () => {
        console.log(`[Coframe] watcher loaded for: ${metricName}`)

        // Normalized text values that qualify as a plan CTA click.
        const qualifyingText = ['buy now', 'try for free', 'or buy now']

        const reportConversion = () => {
            console.log(`[Coframe] ${metricName} detected and metric sent`)
            window.CFQ = window.CFQ || []
            window.CFQ.push({
                emit: 'conversion',
                payload: {
                    metricId: args.metricId
                },
            })
        }

        document.addEventListener('mousedown', function(e) {
            // Only consider clicks on plan-card buttons.
            var btn = e.target.closest('button.dwg-button2')
            if (!btn) return

            var label = (btn.textContent || '').trim().toLowerCase()
            if (qualifyingText.indexOf(label) !== -1) {
                reportConversion()
            }
        }, true)
    }

    if (document.body) startObserver()
    else document.addEventListener('DOMContentLoaded', startObserver)
}

function(args) {
  var metricName = 'Core - Contact Sales Form Submission';
  var LOG_PREFIX = '[DBX-076]';
  var ALLOWED_ORIGIN = 'https://warp-forms.dropbox.com';
  var attachedKey = 'dbx076PostMessageBinderAttached';
  var firedKey = 'dbx076FormSubmissionMetricFired';

  function log(message, details) {
    if (typeof details === 'undefined') {
      console.warn(LOG_PREFIX + ' ' + message);
    } else {
      console.warn(LOG_PREFIX + ' ' + message, details);
    }
  }

  function isContactSalesPage() {
    return window.location.pathname === '/contact-sales' || window.location.pathname === '/contact-sales/';
  }

  log('Metric binder loaded', {
    metricName: metricName,
    pageUrl: window.location.href,
    eligiblePage: isContactSalesPage()
  });

  if (!isContactSalesPage()) {
    log('Not attaching listener because this is not the /contact-sales surface');
    return;
  }

  if (window[attachedKey]) {
    log('Listener already attached; skipping duplicate binder execution');
    return;
  }
  window[attachedKey] = true;

  window.addEventListener('message', function(event) {
    var message = event && event.data;
    var isExpectedMessage = event.origin === ALLOWED_ORIGIN &&
      message &&
      typeof message === 'object' &&
      message.type === 'loading_state_change' &&
      message.data &&
      message.data.state === 'submitted';

    log('postMessage received', {
      origin: event.origin,
      data: message,
      expectedSubmission: isExpectedMessage
    });

    if (!isExpectedMessage) {
      return;
    }

    if (window[firedKey]) {
      log('Submission already recorded on this page; skipping duplicate conversion');
      return;
    }
    window[firedKey] = true;

    log('SUCCESS: Contact Sales form submitted; firing conversion before navigation', {
      metricId: args.metricId,
      origin: event.origin,
      state: message.data.state
    });

    window.CFQ = window.CFQ || [];
    window.CFQ.push({
      emit: 'conversion',
      payload: {
        metricId: args.metricId,
        metricName: metricName
      }
    });
  }, true);

  log('Listening for successful form postMessage events from ' + ALLOWED_ORIGIN);
}

/**
