 * Dedupe:
 * - None. Per canonical metric guide, every genuine click is counted.
 */
function(args) {
    const metricName = 'DBX-050 Demo CTA Click'

    const startObserver = () => {
        console.log(`[Coframe] watcher loaded for: ${metricName}`)

        const reportConversion = () => {
            console.log(`[Coframe] ${metricName} detected and metric sent`)
            window.CFQ = window.CFQ || []
            window.CFQ.push({
                emit: 'conversion',
                payload: {
                    metricId: args.metricId
                },
            })
        }

        const ctaSelector = `a[href='https://sign.dropbox.com/form/contact-us-general'], a[href^='https://sign.dropbox.com/form/contact-us-general'], a[aria-label='Get a demo']`

        document.addEventListener('mousedown', function(e) {
            var match = e.target.closest(ctaSelector)
            if (match) {
