 * - One-time bounded readiness poll for the MktoForms2 global (clears itself; 15s cap).
 *
 * Dedupe:
 * - None. Every validated submission fires a conversion.
 */
function(args) {
    const metricName = 'DBXS-004 Demo Form Submit'

    const startObserver = () => {
        console.log(`[Coframe] watcher loaded for: ${metricName}`)

        const reportConversion = () => {
            console.log(`[Coframe] ${metricName} detected and metric sent`)
