/**
 * Core - /Plans – Annual Plan Selection (Primary metric for DBX-043 Annual Value Badge)
 *
 * Tracks when a visitor selects the YEARLY (annual) billing period on /plans.
 * This is the crux metric for DBX-043: does the green value badge next to the
 * billing toggle increase the share of annual selections?
 *
 * The /plans page has TWO yearly radio inputs (plan cards + plan comparison
 * table), both tagged data-uxa-log="billing_period_yearly_toggle":
 *   <input type="radio" value="yearly" data-uxa-log="billing_period_yearly_toggle">
 * Yearly is CHECKED by default on load. We only count an explicit user
 * SELECTION of yearly (change/click), NOT the default state, so the metric
 * measures active preference toward annual.
 *
 * Tracking method:
 * - Delegated 'change' listener on document (capture phase). Fires whenever a
 *   yearly radio becomes selected via user interaction. Also handles a
 *   delegated 'click' on the yearly <label>/<input> as a fallback for browsers
 *   that route the radio selection through the label.
 * - Matches on data-uxa-log="billing_period_yearly_toggle" so it is resilient
 *   to the dynamic radio-group name suffixes.
 *
 * Dedupe:
 * - None. Every yearly selection is counted (per canonical metric guide §1).
 *   Re-selecting yearly (e.g. toggling monthly -> yearly -> monthly -> yearly)
 *   counts each yearly selection, matching active-preference intent.
 */
function(args) {
    const metricName = 'Core - /Plans – Annual Plan Selection'

    const startObserver = () => {
        console.log(`[Coframe] watcher loaded for: ${metricName}`)

        const yearlySelector = `input[type='radio'][data-uxa-log='billing_period_yearly_toggle']`

        const reportConversion = () => {
            console.log(`[Coframe] ${metricName} detected and metric sent`)
            window.CFQ = window.CFQ || []
            window.CFQ.push({
                emit: 'conversion',
                payload: {
                    metricId: args.metricId
                },
            })
        }

        // Primary: fire when a yearly radio changes to selected via user action.
        document.addEventListener('change', function(e) {
            var radio = e.target.closest(yearlySelector)
            if (radio && radio.checked) {
                reportConversion()
            }
        }, true)

        // Fallback: some UIs route selection through a label click that sets the
        // radio without a bubbling 'change' in capture. Match a mousedown on the
        // yearly control (radio or its wrapping label) that results in selection.
        document.addEventListener('mousedown', function(e) {
            var radio = e.target.closest(yearlySelector)
            if (radio) {
                // If already checked, the change handler above will not fire, but a
                // deliberate mousedown on the yearly control is still an intent to
                // select yearly.
                if (!radio.checked) {
                    reportConversion()
                }
            }
        }, true)
    }

    if (document.body) startObserver()
    else document.addEventListener('DOMContentLoaded', startObserver)
}

