/**
 * Core - /Plans – Paid Conversions (Secondary metric for DBX-043 Annual Value Badge)
 *
 * Tracks completed paid conversions (purchase complete) for visitors who came
 * through the /plans flow. The actual purchase-complete event happens INSIDE
 * Dropbox's authenticated checkout flow (post-payment), which is not observable
 * from the marketing /plans page. The standard pattern is therefore URL-based:
 * fire when the visitor lands on the post-purchase confirmation / success page.
 *
 * ⚠️ VERIFICATION REQUIRED (test log):
 * - The confirmation URL fragments below are BEST-GUESS Dropbox purchase-success
 *   patterns and MUST be verified against the live checkout by completing (or
 *   reaching) a real purchase confirmation before this metric is trusted.
 * - Candidate confirmation signals to confirm in devtools:
 *     * URL contains '/plans/success' or '/checkout/success' or
 *       '/purchase/confirmation' or 'thank-you' / 'order-confirmation'
 *     * a purchase/subscription dataLayer event (if Dropbox pushes one)
 * - Update CONFIRMATION_URL_FRAGMENTS (and/or add a dataLayer branch) once the
 *   real success signal is confirmed. See canonical metric guide §6 & §8.
 *
 * Because Coframe attributes conversions to the visitor via the user token
 * cookie, this metric will attribute the paid conversion back to the /plans
 * experiment exposure even though it fires on a different page — provided the
 * Coframe SDK / user token is present in the checkout flow. If the checkout
 * pages do NOT load the Coframe SDK, this must instead be wired via the
 * Conversion API (server-side, matched by user token) — see the global KB
 * "How to Set Up Manual Conversion Tracking".
 *
 * Tracking method:
 * - URL detection on load + on SPA navigation (popstate / pushState wrap).
 *
 * Dedupe:
 * - None. Fires whenever a confirmation URL is observed (per guide §1).
 */
function(args) {
    const metricName = 'Core - /Plans – Paid Conversions'

    // ⚠️ VERIFY these against the live Dropbox checkout confirmation page.
    const CONFIRMATION_URL_FRAGMENTS = [
        '/plans/success',
        '/checkout/success',
        '/purchase/confirmation',
        '/order-confirmation',
        'thank-you'
    ]

    const startObserver = () => {
        console.log(`[Coframe] watcher loaded for: ${metricName}`)

        const reportConversion = () => {
            console.log(`[Coframe] ${metricName} detected and metric sent`)
            window.CFQ = window.CFQ || []
            window.CFQ.push({
                emit: 'conversion',
                payload: {
                    metricId: args.metricId
                },
            })
        }

        const matchesConfirmation = () => {
            var href = (window.location.href || '').toLowerCase()
            return CONFIRMATION_URL_FRAGMENTS.some(function(frag) {
                return href.indexOf(frag) !== -1
            })
        }

        // Fire on initial load if we are already on a confirmation URL.
        if (matchesConfirmation()) {
            reportConversion()
        }

        // Handle SPA navigations: wrap history.pushState/replaceState + popstate.
        if (!window.__cfPaidConvNavHook) {
            window.__cfPaidConvNavHook = true

            const checkOnNav = function() {
                if (matchesConfirmation()) {
                    reportConversion()
                }
            }

            window.addEventListener('popstate', checkOnNav)

            var origPush = history.pushState
            history.pushState = function() {
                var r = origPush.apply(this, arguments)
                checkOnNav()
                return r
            }

            var origReplace = history.replaceState
            history.replaceState = function() {
                var r = origReplace.apply(this, arguments)
                checkOnNav()
                return r
            }
        }
    }

    if (document.body) startObserver()
    else document.addEventListener('DOMContentLoaded', startObserver)
}

