/**
 * Dropbox Sign - Contact Sales Form – Submit (updated)
 *
 * Tracks successful submissions of the Contact Us form on
 * https://sign.dropbox.com/form/contact-us-general
 *
 * Two success signals, either counts once (deduped via shared `submitted` flag):
 *
 *   A) GTM auto-event listener:
 *      { event: "gtm.formSubmit", "gtm.elementUrl": "https://sign.dropbox.com/form/contact-us-general?..." }
 *      Matched on event + gtm.elementUrl path-prefix (query string varies per session).
 *
 *   B) App-level completion event:
 *      { event: "track_event", eventAction: "/form/contact-us-general",
 *        eventCategory: "contactus-form-complete", eventLabel: "/thankyou" }
 *
 * Pattern (per canonical dataLayer metric rules):
 *  1. Scan existing window.dataLayer entries on init.
 *  2. Wrap dataLayer.push for future events, guarded so we never double-wrap.
 *  3. Per-page dedupe guard (submitted flag) — count once per successful submit.
 */
function(args) {
    const metricName = 'Sign - Contact Sales Form – Submit (updated)'

    const FORM_SUBMIT_EVENT = 'gtm.formSubmit'
    const URL_PREFIX = 'https://sign.dropbox.com/form/contact-us-general'

    const TRACK_EVENT = 'track_event'
    const TRACK_ACTION = '/form/contact-us-general'
    const TRACK_CATEGORY = 'contactus-form-complete'
    const TRACK_LABEL = '/thankyou'

    let submitted = false

    const reportConversion = (sourcePath) => {
        if (submitted) return
        submitted = true
        console.log('[Coframe] ' + metricName + ' detected via ' + sourcePath + ' — metric sent')
        window.CFQ = window.CFQ || []
        window.CFQ.push({
            emit: 'conversion',
            payload: {
                metricId: args.metricId
            },
        })
    }

    const isFormSubmitMatch = (entry) => {
        try {
            if (!entry || typeof entry !== 'object') return false
            if (entry.event !== FORM_SUBMIT_EVENT) return false
            const url = entry['gtm.elementUrl']
            return typeof url === 'string' && url.indexOf(URL_PREFIX) === 0
        } catch (e) {
            return false
        }
    }

    const isTrackEventMatch = (entry) => {
        try {
            if (!entry || typeof entry !== 'object') return false
            return entry.event === TRACK_EVENT &&
                   entry.eventAction === TRACK_ACTION &&
                   entry.eventCategory === TRACK_CATEGORY &&
                   entry.eventLabel === TRACK_LABEL
        } catch (e) {
            return false
        }
    }

    const checkEntry = (entry) => {
        if (isFormSubmitMatch(entry)) {
            reportConversion('dataLayer (gtm.formSubmit)')
            return true
        }
        if (isTrackEventMatch(entry)) {
            reportConversion('dataLayer (track_event / contactus-form-complete)')
            return true
        }
        return false
    }

    const start = () => {
        console.log('[Coframe] watcher loaded for: ' + metricName)
        window.dataLayer = window.dataLayer || []

        try {
            for (let i = 0; i < window.dataLayer.length; i++) {
                if (checkEntry(window.dataLayer[i])) break
            }
        } catch (e) {
            console.warn('[Coframe] ' + metricName + ' dataLayer scan error', e)
        }

        if (!window.dataLayer.__cfContactSubmitUpdatedWrapped) {
            const origPush = window.dataLayer.push
            window.dataLayer.push = function() {
                try {
                    for (let i = 0; i < arguments.length; i++) {
                        checkEntry(arguments[i])
                    }
                } catch (e) {
                    console.warn('[Coframe] ' + metricName + ' push handler error', e)
                }
                return origPush.apply(this, arguments)
            }
            window.dataLayer.__cfContactSubmitUpdatedWrapped = true
        }
    }

    if (document.body) start()
    else document.addEventListener('DOMContentLoaded', start)
}

