  console.warn('[CFQ Metric] js_binder loaded — "' + metricName + '" — waiting for blade or ' + SETTLE_MS + 'ms settle before observing...');

  function fire(what) {
    if (fired) return;
    fired = true;
    console.warn('[CFQ Metric] SUCCESS: "' + metricName + '" — blade zone (' + what + ') entered viewport — firing conversion for metricId: ' + args.metricId);
    window.CFQ = window.CFQ || [];
    window.CFQ.push({
      emit: 'conversion',
      payload: {
        metricId: args.metricId,
        metricName: metricName
      }
    });
    if (io) io.disconnect();
    if (mo) mo.disconnect();
  }

  function resolveTarget() {
    var blade = document.querySelector(BLADE_SEL);
    if (blade) return { el: blade, kind: 'variant blade' };
    var hero = document.querySelector(HERO_SEL);
    if (hero && hero.nextElementSibling) {
      return { el: hero.nextElementSibling, kind: 'control below-hero section' };
    }
    return null;
  }

  function observe(target) {
    if (!target || !target.el || target.el === observedEl) return;
    if (io) io.disconnect();
    observedEl = target.el;
    console.warn('[CFQ Metric] "' + metricName + '" — observing ' + target.kind, observedEl);
    io = new IntersectionObserver(function(entries) {
      for (var i = 0; i < entries.length; i++) {
        if (entries[i].isIntersecting) {
          fire(target.kind);
          return;
        }
      }
    }, { threshold: THRESHOLD });
    io.observe(observedEl);
  }

  function start(reason) {
    if (fired) return;
    started = true;
    var target = resolveTarget();
    if (!target) {
      console.warn('[CFQ Metric] "' + metricName + '" — WARNING: no blade and no hero sibling found at start (' + reason + '); will retry on DOM mutation');
      return;
    }
    observe(target);
  }

