function (args) {
  var metricName = 'Core - Clicks - Plan Card CTA (/business)';

  // Combined plan-card CTA metric for the below-the-fold plan planks on /business.
  //
  // Covers all five plan-card CTAs:
  //   plan_cards_plank_standard_primary_cta     -> "Buy now"
  //   plan_cards_plank_standard_secondary_cta   -> "or try for free"
  //   plan_cards_plank_advanced_primary_cta     -> "Buy now"
  //   plan_cards_plank_advanced_secondary_cta   -> "or try for free"
  //   plan_cards_plank_enterprise_primary_cta   -> "Contact us"
  //
  // NOTE: on /business these CTAs render as <a class="dwg-button2">, NOT <button>.
  // This is why the /plans metric ("Core - [Primary - /Plans] Plan CTA Click"),
  // which matches button.dwg-button2 by text, reads zero on this page.
  //
  // Matched on the stable data-trackingid / data-uxa-log values so the metric is
  // resilient to copy and locale changes.
  //
  // Tracking method: delegated mousedown listener on document (capture phase).
  // mousedown fires before navigation, so the conversion is sent reliably even
  // though these CTAs navigate away to /checkout or /contact-sales.
  //
  // Dedupe: none. Every qualifying click is counted, matching the /plans
  // Plan CTA Click convention so the two pages stay comparable.
  //
  // Page scope: /business and its locale-prefixed variants (e.g. /ja/business).

  var TRACKING_IDS = [
    'plan_cards_plank_standard_primary_cta',
    'plan_cards_plank_standard_secondary_cta',
    'plan_cards_plank_advanced_primary_cta',
    'plan_cards_plank_advanced_secondary_cta',
    'plan_cards_plank_enterprise_primary_cta'
  ];

  var PATH_RE = /^(\/[a-z]{2}(-[a-z]{2})?)?\/business\/?$/i;

  var SELECTOR = TRACKING_IDS.map(function (id) {
    return '[data-trackingid="' + id + '"], [data-uxa-log="' + id + '"]';
  }).join(', ');

  console.warn('[CFQ Metric] js_binder loaded - "' + metricName + '" - starting monitoring...');

  function onPage() {
    return PATH_RE.test(window.location.pathname);
  }

  function fireConversion(id) {
    console.warn('[CFQ Metric] SUCCESS: "' + metricName + '" - plan card CTA clicked (' + id + ') - firing conversion for metricId: ' + args.metricId);
    window.CFQ = window.CFQ || [];
    window.CFQ.push({
      emit: 'conversion',
      payload: {
        metricId: args.metricId,
        metricName: metricName
      }
    });
  }

  function startObserver() {
    var found = document.querySelectorAll(SELECTOR).length;
    if (found > 0) {
      console.warn('[CFQ Metric] "' + metricName + '" - found ' + found + ' plan card CTA(s) on load');
    } else {
      console.warn('[CFQ Metric] "' + metricName + '" - WARNING: no plan card CTAs found yet; delegated listener will still catch them once rendered');
    }

    document.addEventListener('mousedown', function (e) {
      if (!e.target || !e.target.closest) return;
      if (!onPage()) return;

      var cta = e.target.closest(SELECTOR);
      if (!cta) return;

      var id = cta.getAttribute('data-trackingid') || cta.getAttribute('data-uxa-log') || 'unknown';
      if (TRACKING_IDS.indexOf(id) === -1) return;

      fireConversion(id);
    }, true);
  }

  if (document.body) startObserver();
  else document.addEventListener('DOMContentLoaded', startObserver);
}

