(function () {
  'use strict';

  var PAGE_PATH = '/form/contact-us-general';
  var MARKETO_FORM_ID = 19596;
  var CHECKBOX_ID = 'cf-cookie-consent';
  var CONSENT_ROW_ATTRIBUTE = 'data-cookie-consent-row';
  var CONSENT_FIELD = 'cookieConsent';
  var GVC_FIELD = 'gvcId';
  var PRIVACY_URL = 'https://sign.dropbox.com/about/privacy';
  var LOG_PREFIX = '[cookieConsent]';

  // Flip to false once QA is signed off.
  var DEBUG = true;

  // Set once the page guard passes; silences all output elsewhere.
  var isActivePage = false;

  var marketoForm = null;
  var consentCheckbox = null;

  function log() {
    if (!DEBUG || !isActivePage) {
      return;
    }

    console.log.apply(
      console,
      [LOG_PREFIX].concat(Array.prototype.slice.call(arguments))
    );
  }

  function warn() {
    if (!isActivePage) {
      return;
    }

    console.warn.apply(
      console,
      [LOG_PREFIX].concat(Array.prototype.slice.call(arguments))
    );
  }

  function isTargetPage() {
    return window.location.pathname.replace(/\/+$/, '') === PAGE_PATH;
  }

  function readCookie(name) {
    var escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    var match = document.cookie.match(
      new RegExp('(?:^|;)\\s*' + escapedName + '\\s*=\\s*([^;]*)')
    );

    if (!match) {
      return '';
    }

    try {
      return decodeURIComponent(match[1]);
    } catch (error) {
      return match[1];
    }
  }

  function getAnalyticsId() {
    var analyticsId = readCookie('dbx_js_analytics_id');

    if (!analyticsId) {
      warn('dbx_js_analytics_id cookie is empty; gvcId will be blank.');
    }

    return analyticsId;
  }

  function getConsentState() {
    var raw = readCookie('__Secure-dbx_consent');

    if (!raw) {
      return { interacted: false, granted: false };
    }

    try {
      var parsed = JSON.parse(raw);
      var categories = parsed.categories || {};
      var granted = categories.all === true || categories.analytics === true;
      var interacted = parsed.userInteracted === true;

      log('consent cookie', {
        granted: granted,
        userInteracted: interacted,
        categories: categories
      });

      return { interacted: interacted, granted: granted };
    } catch (error) {
      warn('could not parse __Secure-dbx_consent:', error);
      return { interacted: false, granted: false };
    }
  }

  function hasCookieConsent() {
    return getConsentState().granted;
  }

  // True only once the visitor has made an actual choice on the banner
  // (userInteracted: true) and that choice was not consent. The default,
  // no-cookie-yet state is "unknown," not "denied," and doesn't qualify.
  function isConsentExplicitlyDenied() {
    var state = getConsentState();
    return state.interacted && !state.granted;
  }

  // Consent exists when the banner already grants analytics, or when the
  // visitor ticks our checkbox.
  function isConsentAllowed() {
    return hasCookieConsent() || !!(consentCheckbox && consentCheckbox.checked);
  }

  function buildConsentValues() {
    var allowed = isConsentAllowed();
    var values = {};

    values[CONSENT_FIELD] = allowed ? 'true' : 'false';
    values[GVC_FIELD] = allowed ? getAnalyticsId() : '';

    return values;
  }

  // ─── Marketo layer ──────────────────────────────────────────────────────────
  // The page's variant code builds its own allowlist payload and calls
  // setValues() right before submit, so inputs we add to the visible form are
  // never read; we write through the Marketo form instead.

  // setValues() only writes fields Marketo already knows, so back it up by
  // writing the inputs inside the Marketo form element directly.
  function writeHiddenInputs(form, values) {
    var formElem = form.getFormElem && form.getFormElem();
    var root = formElem && formElem[0];

    if (!root) {
      warn('Marketo form element not available; hidden inputs not written.');
      return;
    }

    Object.keys(values).forEach(function (name) {
      var inputs = root.querySelectorAll('[name="' + name + '"]');

      if (!inputs.length) {
        var input = document.createElement('input');
        input.type = 'hidden';
        input.name = name;
        input.value = values[name];
        root.appendChild(input);
        return;
      }

      // Marketo can end up with more than one input per name; set them all so
      // whichever one serializes carries the value.
      for (var index = 0; index < inputs.length; index++) {
        inputs[index].value = values[name];
      }
    });
  }

  // Mirror the same values onto the visible form so they're present wherever the
  // variant's submit path reads from, and visible in its own network payload.
  function writeVisibleFormFields(values) {
    var form = getVisibleForm();

    if (!form) {
      return;
    }

    Object.keys(values).forEach(function (name) {
      var input = form.querySelector('input[type="hidden"][name="' + name + '"]');

      if (!input) {
        input = document.createElement('input');
        input.type = 'hidden';
        input.name = name;
        form.appendChild(input);
      }

      input.value = values[name];
    });
  }

  function applyConsentValues() {
    var values = buildConsentValues();

    writeVisibleFormFields(values);

    if (!marketoForm) {
      log('applied to visible form only (Marketo form not ready)', values);
      return;
    }

    marketoForm.setValues(values);
    writeHiddenInputs(marketoForm, values);

    log('applied to Marketo form', values);
  }

  function mergeConsentValues(values) {
    var merged = {};
    var key;

    for (key in values) {
      if (Object.prototype.hasOwnProperty.call(values, key)) {
        merged[key] = values[key];
      }
    }

    var consentValues = buildConsentValues();

    for (key in consentValues) {
      if (Object.prototype.hasOwnProperty.call(consentValues, key)) {
        merged[key] = consentValues[key];
      }
    }

    return merged;
  }

  function wrapMarketoForm(form) {
    if (form.cfConsentWrapped) {
      return;
    }

    form.cfConsentWrapped = true;

    var originalSetValues = form.setValues;
    var originalSubmit = form.submit;

    form.setValues = function (values) {
      return originalSetValues.call(this, mergeConsentValues(values));
    };

    // Last write wins: re-assert after the variant's payload, right before the
    // request is built.
    form.submit = function () {
      var values = buildConsentValues();

      originalSetValues.call(this, values);
      writeHiddenInputs(this, values);

      var current = this.getValues();

      log('re-asserted at submit', values, 'form now reports', {
        cookieConsent: current[CONSENT_FIELD],
        gvcId: current[GVC_FIELD]
      });

      return originalSubmit.apply(this, arguments);
    };
  }

  function attachToMarketoForm() {
    var marketo = window.MktoForms2;

    if (!marketo || typeof marketo.getForm !== 'function') {
      return false;
    }

    var form = marketo.getForm(MARKETO_FORM_ID);

    if (!form) {
      return false;
    }

    marketoForm = form;

    // Marketo drops values for fields the form doesn't know about, so declare
    // them with their real values. Harmless once they exist on the published form.
    if (typeof form.addHiddenFields === 'function') {
      form.addHiddenFields(buildConsentValues());
    }

    wrapMarketoForm(form);

    // The page ships its own gvcid-marketo-injector.js, whose onSubmit handler
    // clears gvcId unless the consent cookie grants analytics or a checkbox named
    // cookieConsent inside the Marketo form is checked — neither is true when the
    // visitor ticks our checkbox instead. Marketo runs onSubmit handlers in
    // registration order and this tag loads after that script, so re-asserting
    // here lands after its clear and before the request is serialized.
    if (typeof form.onSubmit === 'function') {
      form.onSubmit(function (submittingForm) {
        var values = buildConsentValues();

        writeHiddenInputs(submittingForm, values);
        log('re-asserted after page injector', values);
      });
    }

    applyConsentValues();

    log('attached to Marketo form', MARKETO_FORM_ID);

    return true;
  }

  function waitForMarketoForm() {
    if (attachToMarketoForm()) {
      return;
    }

    var attempts = 0;

    var timer = window.setInterval(function () {
      attempts += 1;

      if (attachToMarketoForm() || attempts > 60) {
        window.clearInterval(timer);

        if (!marketoForm) {
          warn('Marketo form', MARKETO_FORM_ID, 'never became available.');
        }
      }
    }, 250);
  }

  // ─── Checkbox UI ────────────────────────────────────────────────────────────
  function getVisibleForm() {
    var forms = document.querySelectorAll('form');

    for (var formIndex = 0; formIndex < forms.length; formIndex++) {
      var form = forms[formIndex];

      // Marketo's own hidden form also has an email input and a submit button,
      // so skip it explicitly — the checkbox belongs on the variant's form.
      if (form.querySelector('input[name="munchkinId"]')) {
        continue;
      }

      if (
        form.querySelector('input[name="marketingOptin"]') ||
        (form.querySelector('input[type="email"]') &&
          form.querySelector('.cf-submit-btn, button[type="submit"]'))
      ) {
        return form;
      }
    }

    return null;
  }

  function createConsentCheckbox(form) {
    var existing = form.querySelector('#' + CHECKBOX_ID);

    if (existing) {
      return existing;
    }

    var marketingCheckbox = form.querySelector('input[name="marketingOptin"]');

    var insertionPoint = marketingCheckbox
      ? marketingCheckbox.parentElement
      : form.querySelector('.cf-submit-btn, button[type="submit"]');

    if (!insertionPoint || !insertionPoint.parentNode) {
      warn('no insertion point for the consent row; checkbox not rendered.');
      return null;
    }

    var row = document.createElement('div');
    row.className = 'cf:flex cf:gap-3 cf:mb-5 cf:items-start';
    row.setAttribute('data-cookie-consent-row', 'true');

    var checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = CHECKBOX_ID;
    checkbox.name = 'cookieConsentUI';
    checkbox.value = 'true';
    checkbox.checked = false;
    checkbox.className = 'cf:mt-1 cf:flex-shrink-0';
    checkbox.style.cssText =
      'width:16px;height:16px;cursor:pointer;';

    var label = document.createElement('label');
    label.htmlFor = CHECKBOX_ID;
    label.className =
      'cf:text-[13px] cf:text-[#333] cf:leading-snug cf:cursor-pointer';
    label.style.cssText =
      'font-family:"Atlas Grotesk",sans-serif;font-weight:400;';

    label.appendChild(
      document.createTextNode(
        'I consent to Dropbox using a cookie for the purpose of measuring and improving the effectiveness of our content. '
      )
    );

    var privacyLink = document.createElement('a');
    privacyLink.href = PRIVACY_URL;
    privacyLink.target = '_blank';
    privacyLink.rel = 'noopener noreferrer';
    privacyLink.textContent = 'Privacy Policy';
    privacyLink.style.cssText = 'color:#0061FE;text-decoration:underline;cursor:pointer;';

    label.appendChild(privacyLink);
    label.appendChild(document.createTextNode('.'));

    row.appendChild(checkbox);
    row.appendChild(label);

    insertionPoint.parentNode.insertBefore(row, insertionPoint);

    checkbox.addEventListener('change', function () {
      log('checkbox toggled to', checkbox.checked);
      applyConsentValues();
    });

    return checkbox;
  }

  function syncCheckboxVisibility() {
    var form = getVisibleForm();

    if (!form) {
      return;
    }

    var denied = isConsentExplicitlyDenied();

    if (!denied) {
      // Consent is either granted or still undecided — the checkbox/label
      // shouldn't exist in the DOM until we've explicitly seen a denial.
      var existingRow = form.querySelector('[' + CONSENT_ROW_ATTRIBUTE + '="true"]');

      if (existingRow && existingRow.parentNode) {
        existingRow.parentNode.removeChild(existingRow);
      }

      consentCheckbox = null;

      log('checkbox not rendered — consent state:', hasCookieConsent() ? 'granted' : 'unknown');

      applyConsentValues();
      return;
    }

    if (!consentCheckbox || !form.contains(consentCheckbox)) {
      consentCheckbox = createConsentCheckbox(form);
    }

    if (!consentCheckbox) {
      return;
    }

    log('checkbox visible: true (explicit denial)');

    applyConsentValues();
  }

  // ─── Consent changes ────────────────────────────────────────────────────────
  function attachConsentCallback() {
    var previousCallback = window.consentChangedCallback;

    window.consentChangedCallback = function () {
      if (typeof previousCallback === 'function') {
        previousCallback.apply(this, arguments);
      }

      log('consentChangedCallback fired');

      window.setTimeout(syncCheckboxVisibility, 100);
    };
  }

  // Cookie writes fire no DOM event, so poll as a fallback for banner
  // interactions that bypass the callback.
  function watchConsentCookie() {
    var previousCookie = readCookie('__Secure-dbx_consent');

    window.setInterval(function () {
      var currentCookie = readCookie('__Secure-dbx_consent');

      if (currentCookie !== previousCookie) {
        previousCookie = currentCookie;
        log('consent cookie changed outside the callback; resyncing.');
        syncCheckboxVisibility();
      }
    }, 500);
  }

  // The variant renders the form client-side, so it may appear after we run.
  function watchForFormRendering() {
    if (!document.body || !window.MutationObserver) {
      return;
    }

    var observer = new MutationObserver(function () {
      var form = getVisibleForm();

      if (form && !form.querySelector('#' + CHECKBOX_ID)) {
        syncCheckboxVisibility();
      }
    });

    observer.observe(document.body, { childList: true, subtree: true });
  }

  function initialize() {
    if (!isTargetPage()) {
      return;
    }

    isActivePage = true;

    log('initializing on', window.location.pathname);

    attachConsentCallback();
    waitForMarketoForm();
    syncCheckboxVisibility();
    watchConsentCookie();
    watchForFormRendering();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initialize);
  } else {
    initialize();
  }
})();
